CREATE TYPE "TransactionType" AS ENUM ('INCOME','EXPENSE');
CREATE TYPE "BillStatus" AS ENUM ('PAID','PENDING','OVERDUE');
CREATE TYPE "GoalType" AS ENUM ('REVENUE','SAVINGS','OTHER');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Category" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"type" "TransactionType" NOT NULL,"color" TEXT NOT NULL DEFAULT '#6C5CE7',"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "Category_userId_name_type_key" ON "Category"("userId","name","type");
CREATE TABLE "Transaction" ("id" TEXT PRIMARY KEY,"description" TEXT NOT NULL,"amount" DECIMAL(12,2) NOT NULL,"date" TIMESTAMP(3) NOT NULL,"type" "TransactionType" NOT NULL,"paymentMethod" TEXT,"notes" TEXT,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"categoryId" TEXT REFERENCES "Category"("id") ON DELETE SET NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Transaction_userId_date_type_idx" ON "Transaction"("userId","date","type");
CREATE TABLE "Bill" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"amount" DECIMAL(12,2) NOT NULL,"dueDay" INTEGER NOT NULL,"category" TEXT NOT NULL,"recurring" BOOLEAN NOT NULL DEFAULT true,"paymentMethod" TEXT,"status" "BillStatus" NOT NULL DEFAULT 'PENDING',"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "Vehicle" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"avgConsumption" DECIMAL(8,2),"financingMonthly" DECIMAL(12,2),"insuranceMonthly" DECIMAL(12,2),"maintenanceMonthly" DECIMAL(12,2),"annualTax" DECIMAL(12,2),"depreciationMonthly" DECIMAL(12,2),"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "Journey" ("id" TEXT PRIMARY KEY,"date" TIMESTAMP(3) NOT NULL,"startTime" TIMESTAMP(3) NOT NULL,"endTime" TIMESTAMP(3) NOT NULL,"startKm" DECIMAL(10,1) NOT NULL,"endKm" DECIMAL(10,1) NOT NULL,"uber" DECIMAL(12,2) NOT NULL DEFAULT 0,"ninetyNine" DECIMAL(12,2) NOT NULL DEFAULT 0,"inDrive" DECIMAL(12,2) NOT NULL DEFAULT 0,"otherApps" DECIMAL(12,2) NOT NULL DEFAULT 0,"tips" DECIMAL(12,2) NOT NULL DEFAULT 0,"otherIncome" DECIMAL(12,2) NOT NULL DEFAULT 0,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"vehicleId" TEXT REFERENCES "Vehicle"("id") ON DELETE SET NULL);
CREATE TABLE "JourneyCost" ("id" TEXT PRIMARY KEY,"category" TEXT NOT NULL,"amount" DECIMAL(12,2) NOT NULL,"notes" TEXT,"journeyId" TEXT NOT NULL REFERENCES "Journey"("id") ON DELETE CASCADE);
CREATE TABLE "Fueling" ("id" TEXT PRIMARY KEY,"date" TIMESTAMP(3) NOT NULL,"liters" DECIMAL(10,3) NOT NULL,"pricePerLiter" DECIMAL(10,3) NOT NULL,"total" DECIMAL(12,2) NOT NULL,"odometer" DECIMAL(10,1) NOT NULL,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"vehicleId" TEXT REFERENCES "Vehicle"("id") ON DELETE SET NULL);
CREATE TABLE "Goal" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"type" "GoalType" NOT NULL,"target" DECIMAL(12,2) NOT NULL,"current" DECIMAL(12,2) NOT NULL DEFAULT 0,"month" INTEGER,"year" INTEGER,"workDays" INTEGER,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "Vault" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"target" DECIMAL(12,2) NOT NULL,"balance" DECIMAL(12,2) NOT NULL DEFAULT 0,"color" TEXT NOT NULL DEFAULT '#6C5CE7',"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "Setting" ("id" TEXT PRIMARY KEY,"monthlySalary" DECIMAL(12,2),"avgFuelPrice" DECIMAL(10,3),"onboardingDone" BOOLEAN NOT NULL DEFAULT false,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "Setting_userId_key" ON "Setting"("userId");
